def clean(df):
    df['Price'] = df['Price'].str.replace('$', '').astype(float)
    df = df.dropna(subset=['Region'])
    df['Region'] = df['Region'].str.strip().replace({'Wst': 'West', 'Eats': 'East', ' West': 'West', 'East ': 'East'})
    df = df[df['Quantity'] > 0]
    return df

def answer(df):
    df = df.groupby('Category')['Price'].mean().reset_index()
    return dict(df.values.tolist())
